#!/usr/bin/perl
# g21_cycles.pl -- THE CYCLE-GROWTH CONSTANT'S COUNT: CONNECTED RELATIVE 2-CYCLES OF Z^4 PLAQUETTES MODULO THE COARSE SKELETON (ΠΕΝΤΑΠΥΛΟΝ G21,
# 2026-10-29 01:0x EDT, the desktop seat; the plan seat's class of 00:5x, for the layered expansion's radius at the decision point B5c).
#
# THE CLASS.  Z^4 with the coarse lattice 2Z^4; a fine link x -> x + e_mu is COARSE iff x_nu is even for every nu != mu, FREE otherwise.  A finite
# set P of fine plaquettes is a RELATIVE 2-CYCLE iff every FREE link lies in an even number of plaquettes of P (the coarse links unconstrained);
# CONNECTED iff its plaquettes are joined through shared links.  N_n = the number of connected relative 2-cycles of n plaquettes containing a
# fixed plaquette p_0 (the class is 2Z^4-invariant only, so p_0's position matters: 'even' = the (1,2)-plaquette at the origin, whose transverse
# coordinates are even -- it lies in a coarse 2x2 patch; 'odd' = the (1,2)-plaquette at (0,0,1,0)).  mu = lim N_n^{1/n}.
# THE KNOWN ANSWERS (hand): no single plaquette is in the class (its two parallel links cannot both be coarse); no pair (they would share two
# links); N_4 = 1 at the even position (the coarse patch) and 0 at the odd; N_6 >= 4 (the four cubes through p_0, every edge of a cube in two
# of its faces); two cubes sharing a face give a 10-cycle.
# TWO ROADS.  (A) Redelmeier's rooted-animal enumeration on the plaquette graph (adjacent iff a shared link; degree 20), each connected set
# containing p_0 once, pruned by the parity: a set with O odd free links needs at least ceil(O/4) more plaquettes; counted at closure (O = 0).
# (B) the generator road: the relative cycle space is generated by cube boundaries and coarse 2x2 patches (H_2(Z^4) = 0 makes every 2-cycle a
# sum of cube boundaries; a chain whose boundary is a coarse 1-cycle differs from a sum of patches by a cycle), so sums of <= K generators from a
# box round p_0 are formed, their supports deduplicated and read for size, connectivity and p_0 -- complete at weight n if every such cycle is a
# sum of <= K generators (checked against road A where both reach; stated as a floor where only B reaches).
# usage: perl g21_cycles.pl A NMAX [pos=even|odd]      perl g21_cycles.pl B K BOX NMAX [pos]
use strict; use warnings; $| = 1;
my ($MODE, @A) = @ARGV; die "usage: A NMAX [pos] | B K BOX NMAX [pos]" unless defined $MODE;
sub coarse { my ($x, $mu) = @_; for my $nu (0 .. 3) { next if $nu == $mu; return 0 if $x->[$nu] % 2 } return 1 }
sub lkey { my ($x, $mu) = @_; return join(',', @$x) . ":$mu" }
sub pkey { my ($x, $mu, $nu) = @_; return join(',', @$x) . ":$mu$nu" }
sub punkey { my $k = shift; my ($c, $d) = split /:/, $k; my @x = split /,/, $c; return (\@x, substr($d, 0, 1), substr($d, 1, 1)) }
sub links_of { my ($x, $mu, $nu) = @_; my @xm = @$x; $xm[$mu]++; my @xn = @$x; $xn[$nu]++; return ([ $x, $mu ], [ \@xm, $nu ], [ \@xn, $mu ], [ $x, $nu ]) }   # x->x+mu, x+mu->+nu, x+nu->+mu, x->x+nu
my %LFREE; sub lfree { my ($x, $mu) = @_; my $k = lkey($x, $mu); return $LFREE{$k} //= (coarse($x, $mu) ? 0 : 1) }
my %NBR; sub nbrs { my $pk = shift; return $NBR{$pk} if exists $NBR{$pk}; my ($x, $mu, $nu) = punkey($pk); my %n;
  for my $l (links_of($x, $mu, $nu)) { my ($lx, $lm) = @$l; for my $rho (0 .. 3) { next if $rho == $lm; my ($a, $b) = sort { $a <=> $b } ($lm, $rho); $n{ pkey($lx, $a, $b) } = 1; my @y = @$lx; $y[$rho]--; $n{ pkey(\@y, $a, $b) } = 1 } }
  delete $n{$pk}; return $NBR{$pk} = [ sort keys %n ] }
my $pos = ($MODE eq 'A') ? ($A[1] // 'even') : ($A[3] // 'even'); my $P0 = ($pos eq 'even') ? pkey([0, 0, 0, 0], 0, 1) : pkey([0, 0, 1, 0], 0, 1);
my %LINKSOF; sub linkkeys { my $pk = shift; return $LINKSOF{$pk} if exists $LINKSOF{$pk}; my ($x, $mu, $nu) = punkey($pk); return $LINKSOF{$pk} = [ map { [ lkey(@$_), lfree(@$_) ] } links_of($x, $mu, $nu) ] }
my $t0 = time;
if ($MODE eq 'A') { my $NMAX = $A[0] // 8; my @N = (0) x ($NMAX + 1); my %par; my $odd = 0; my @set; my %inset; my %seen; my $nodes = 0; my %small;
  sub flip { my ($pk, $dir) = @_; for my $l (@{ linkkeys($pk) }) { my ($lk, $fr) = @$l; next unless $fr; $par{$lk} = ($par{$lk} // 0) ^ 1; $odd += $par{$lk} ? 1 : -1 } }
  # Redelmeier: untried set U; take a cell c from U, add it, recurse with U' = U + (new neighbours of c not seen); then remove c and continue with the rest of U (c stays forbidden)
  my $rec; $rec = sub { my ($untried, $size) = @_; my @U = @$untried; my %local;
    while (@U) { my $c = shift @U; $nodes++; push @set, $c; $inset{$c} = 1; flip($c, 1); my $k = $size + 1;
      if ($odd == 0) { $N[$k]++; if ($k <= 6 && $small{$k}++ < 3) { print "G21-CYCLE n=$k: ", join(' ', sort @set), "\n" } }
      if ($k < $NMAX && $odd <= 4 * ($NMAX - $k)) { my @new; for my $q (@{ nbrs($c) }) { next if $seen{$q} || $inset{$q}; $seen{$q} = 1; $local{$q} = 1; push @new, $q } $rec->([@U, @new], $k); delete $seen{$_} for @new; delete $local{$_} for @new }
      flip($c, -1); delete $inset{$c}; pop @set } };
  $seen{$P0} = 1; $rec->([$P0], 0);
  printf "G21-A pos=%s p0=%s NMAX=%d nodes=%d (%d s)\n", $pos, $P0, $NMAX, $nodes, time - $t0;
  for my $n (1 .. $NMAX) { printf "G21-N road=A pos=%s n=%d N_n=%d%s\n", $pos, $n, $N[$n], ($n > 1 && $N[$n - 1] > 0) ? sprintf(" ratio=%.4f", $N[$n] / $N[$n - 1]) : '' }
  my ($last) = grep { $N[$_] > 0 } reverse 1 .. $NMAX; printf "G21-A-VERDICT pos=%s N_4=%d N_6=%d N_8=%d N_10=%d; the last ratio N_%d/N_%d = %.4f is a reading, not mu\n", $pos, $N[4], $N[6], $N[8] // 0, $N[10] // 0, $last, $last - 1, $N[$last - 1] ? $N[$last] / $N[$last - 1] : 0; exit }
if ($MODE eq 'B') { my ($K, $BOX, $NMAX) = @A; $K //= 3; $BOX //= 2; $NMAX //= 12; my ($x0) = punkey($P0);
  my @gen;                                                                                        # generators: cube boundaries and coarse patches within the box round p0
  for my $a (-$BOX .. $BOX) { for my $b (-$BOX .. $BOX) { for my $c (-$BOX .. $BOX) { for my $d (-$BOX .. $BOX) { my @x = ($x0->[0] + $a, $x0->[1] + $b, $x0->[2] + $c, $x0->[3] + $d);
    for my $i (0 .. 3) { for my $j ($i + 1 .. 3) { for my $k ($j + 1 .. 3) { my %f; for my $pair ([$i, $j, $k], [$i, $k, $j], [$j, $k, $i]) { my ($u, $v, $w) = @$pair; for my $s (0, 1) { my @y = @x; $y[$w] += $s; $f{ pkey(\@y, $u, $v) } = 1 } } push @gen, [ 'cube', [ sort keys %f ] ] } } }
    next if grep { $_ % 2 } @x; for my $i (0 .. 3) { for my $j ($i + 1 .. 3) { my %f; for my $s (0, 1) { for my $t (0, 1) { my @y = @x; $y[$i] += $s; $y[$j] += $t; $f{ pkey(\@y, $i, $j) } = 1 } } push @gen, [ 'patch', [ sort keys %f ] ] } } } } } }
  my $ng = scalar @gen; printf "G21-B pos=%s K=%d BOX=%d generators=%d (%d cubes)\n", $pos, $K, $BOX, $ng, scalar grep { $_->[0] eq 'cube' } @gen;
  my %gwith; for my $g (0 .. $ng - 1) { for my $p (@{$gen[$g][1]}) { push @{$gwith{$p}}, $g } }
  my %found; my @N = (0) x ($NMAX + 1); my %small;
  my $connected = sub { my $S = shift; my %s = map { $_ => 1 } @$S; my @st = ($S->[0]); my %v = ($S->[0] => 1); while (@st) { my $c = pop @st; for my $q (@{ nbrs($c) }) { if ($s{$q} && !$v{$q}) { $v{$q} = 1; push @st, $q } } } return scalar(keys %v) == scalar @$S };
  my $read = sub { my $sup = shift; my @S = sort keys %$sup; my $n = scalar @S; return if $n == 0 || $n > $NMAX || !$sup->{$P0}; my $key = join('|', @S); return if $found{$key}++; return unless $connected->(\@S);
    for my $l (@S) { for my $lk (@{ linkkeys($l) }) { } } my %par; for my $p (@S) { for my $lk (@{ linkkeys($p) }) { next unless $lk->[1]; $par{$lk->[0]} ^= 1 } } die "generator sum not a relative cycle" if grep { $_ } values %par;
    $N[$n]++; if ($ENV{G21_ALL} ? ($n <= $ENV{G21_ALL}) : ($small{$n}++ < 2)) { print "G21-CYCLE road=B n=$n: ", join(' ', @S), "\n" } };   # G21_ALL=n prints every member to size n
  # sums of <= K generators that include p0: the first generator must contain p0 (else p0 would have to enter later -- so enumerate ordered by index with at least one containing p0)
  my @g0 = @{ $gwith{$P0} // [] }; printf "G21-B %d generators contain p0\n", scalar @g0;
  # each generator after the first must TOUCH the running support (share a plaquette with it or with a neighbour of it): a connected cycle's generators
  # can be ordered so; the first generator contains p0 (ordered sums: every later generator has a larger index than the first only when it does not contain p0 -- so
  # the first is any generator through p0 and the rest are any touching generators with index != the first's, counted once by requiring increasing indices among them)
  my $rec; $rec = sub { my ($sup, $used, $depth) = @_; $read->($sup) if $sup->{$P0}; return if $depth >= $K;
    my %touch; for my $q (keys %$sup) { $touch{$_} = 1 for @{ $gwith{$q} // [] }; for my $r (@{ nbrs($q) }) { $touch{$_} = 1 for @{ $gwith{$r} // [] } } }
    for my $g (sort { $a <=> $b } keys %touch) { next if $used->{$g}; next if $g < $used->{last}; my %s = %$sup; for my $p (@{$gen[$g][1]}) { if ($s{$p}) { delete $s{$p} } else { $s{$p} = 1 } }
      next if scalar(keys %s) > $NMAX + 6 * ($K - $depth - 1); my %u = %$used; $u{$g} = 1; $u{last} = $g; $rec->(\%s, \%u, $depth + 1) } };
  for my $g0 (@g0) { my %s = map { $_ => 1 } @{$gen[$g0][1]}; $rec->(\%s, { $g0 => 1, last => -1 }, 1) }
  printf "G21-B done: %d distinct cycles read (%d s)\n", scalar keys %found, time - $t0;
  for my $n (1 .. $NMAX) { printf "G21-N road=B pos=%s n=%d N_n>=%d%s\n", $pos, $n, $N[$n], ($n > 1 && $N[$n - 1] > 0) ? sprintf(" ratio=%.4f", $N[$n] / $N[$n - 1]) : '' } exit }
